#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-31

# Unit test for src/skills/dream/scripts/index-budget.mjs (#3741)
#
# Synthetic memory directories built under mktemp with ages set by `touch -t`.
# Pins: an over-budget index proposes moves that are all rule-eligible (never
# hub_/user_/Policy/fresh); an under-budget index proposes none; a dry run
# leaves both index files byte-identical; --apply keeps the two-file 1:1
# invariant, a single trailer, and lands under the ceiling; and dream's
# SKILL.md no longer carries the stale "200 lines" rule.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
TOOL="$REPO_ROOT/src/skills/dream/scripts/index-budget.mjs"
SKILL="$REPO_ROOT/src/skills/dream/SKILL.md"

if [[ ! -f "$TOOL" ]]; then
    echo "FAIL: $TOOL not found" >&2
    exit 1
fi

TMP="$(mktemp -d "${TMPDIR:-/tmp}/ork.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT

PASS=0
FAIL=0
ok()   { echo "  ✓ $1"; PASS=$((PASS + 1)); }
bad()  { echo "  ✗ $1"; FAIL=$((FAIL + 1)); }
# eval here and in jsonq run only string literals written in THIS file (test conditions
# and JSON path expressions), never input from the tool under test or the environment.
check() { if eval "$2"; then ok "$1"; else bad "$1"; fi; }
jsonq() { node -e 'const r=JSON.parse(require("fs").readFileSync(process.argv[1],"utf8"));console.log(eval(process.argv[2]))' "$1" "$2"; }

OLD_STAMP="202601010000"   # 2026-01-01, far older than any threshold

# Build a memory dir with N entries per class. Handoff filenames carry their date.
build_dir() {
    local dir="$1" handoffs="$2" feedback="$3" hubs="$4"
    mkdir -p "$dir"
    {
        echo "# Test Memory"
        echo ""
        echo "## Hubs ($hubs)"
        for i in $(seq 1 "$hubs" 2>/dev/null | awk -v n="$hubs" 'n>0'); do  # silent: known-noise -- macOS seq 1 0 counts DOWN; the awk guard keeps zero-count classes empty
            printf -- '---\nname: hub-%s\n---\nhub\n' "$i" > "$dir/hub_$i.md"
            touch -t "$OLD_STAMP" "$dir/hub_$i.md"
            echo "- [hub $i](hub_$i.md) · index of things number $i with a long enough hook to carry bytes into the budget"
        done
        echo ""
        echo "## Policy (1)"
        printf -- '---\nname: policy\n---\npolicy\n' > "$dir/feedback_policy_rule.md"
        touch -t "$OLD_STAMP" "$dir/feedback_policy_rule.md"
        echo "- [policy rule](feedback_policy_rule.md) · never moved even though it is old"
        echo ""
        echo "## Handoffs"
        for i in $(seq 1 "$handoffs" 2>/dev/null | awk -v n="$handoffs" 'n>0'); do  # silent: known-noise -- same seq guard
            local f="project_handoff_2026_01_$(printf '%02d' "$i")_thing.md"
            printf -- '---\nname: handoff-%s\n---\nhandoff\n' "$i" > "$dir/$f"
            touch -t "$OLD_STAMP" "$dir/$f"
            echo "- [01-$i handoff](${f}) · a handoff line long enough to carry bytes into the budget for the test fixture number $i"
        done
        echo ""
        echo "## Feedback ($feedback)"
        for i in $(seq 1 "$feedback" 2>/dev/null | awk -v n="$feedback" 'n>0'); do  # silent: known-noise -- same seq guard
            printf -- '---\nname: fb-%s\n---\nfb\n' "$i" > "$dir/feedback_item_$i.md"
            touch -t "$OLD_STAMP" "$dir/feedback_item_$i.md"
            echo "- [feedback $i](feedback_item_$i.md) · an old feedback entry with a hook long enough to carry bytes into the budget $i"
        done
        echo ""
        echo "## Reference & User (1)"
        printf -- '---\nname: user\n---\nuser\n' > "$dir/user_profile.md"
        touch -t "$OLD_STAMP" "$dir/user_profile.md"
        echo "- [user profile](user_profile.md) · never moved"
        echo ""
        echo "> $((hubs + 1 + handoffs + feedback + 1)) memory files total. Every file is indexed exactly once across this file and [MEMORY-ARCHIVE.md](MEMORY-ARCHIVE.md)."
    } > "$dir/MEMORY.md"
}

echo "index-budget.mjs"

# 1. over budget: a tiny ceiling forces moves; all must be rule-eligible
build_dir "$TMP/over" 6 6 2
node "$TOOL" "$TMP/over" --ceiling 900 --json > "$TMP/over.json"
MOVES=$(jsonq "$TMP/over.json" 'r.proposed_moves.length')
check "over-budget index proposes at least one move ($MOVES)" '[[ "$MOVES" -ge 1 ]]'
BADMOVES=$(jsonq "$TMP/over.json" 'r.proposed_moves.filter(m=>/^(hub_|user_)/.test(m.file)||m.section==="Policy").length')
check "no hub_/user_/Policy entry is ever proposed" '[[ "$BADMOVES" -eq 0 ]]'
FIRST=$(jsonq "$TMP/over.json" 'r.proposed_moves[0].section')
check "handoffs are proposed before feedback/project" '[[ "$FIRST" == "Handoffs" ]]'
INV=$(jsonq "$TMP/over.json" 'r.invariant.ok')
check "fixture invariant holds before any move" '[[ "$INV" == "true" ]]'

# 2. dry run leaves the index byte-identical and creates no archive
SHA_BEFORE=$(shasum -a 256 "$TMP/over/MEMORY.md" | cut -d' ' -f1)
node "$TOOL" "$TMP/over" --ceiling 900 > /dev/null
SHA_AFTER=$(shasum -a 256 "$TMP/over/MEMORY.md" | cut -d' ' -f1)
check "dry run does not modify MEMORY.md" '[[ "$SHA_BEFORE" == "$SHA_AFTER" ]]'
check "dry run creates no archive" '[[ ! -e "$TMP/over/MEMORY-ARCHIVE.md" ]]'

# 3. under budget: no moves
build_dir "$TMP/under" 2 2 1
node "$TOOL" "$TMP/under" --ceiling 100000 --json > "$TMP/under.json"
MOVES=$(jsonq "$TMP/under.json" 'r.proposed_moves.length')
check "under-budget index proposes zero moves" '[[ "$MOVES" -eq 0 ]]'

# 4. fresh files are never moved even when old by name
build_dir "$TMP/fresh" 3 0 0
touch "$TMP/fresh"/project_handoff_2026_01_0*_thing.md
node "$TOOL" "$TMP/fresh" --ceiling 100 --json > "$TMP/fresh.json"
MOVES=$(jsonq "$TMP/fresh.json" 'r.proposed_moves.length')
check "files modified within 7 days are never proposed" '[[ "$MOVES" -eq 0 ]]'

# 5. apply: invariant holds, one trailer, under ceiling, .prev rotated
build_dir "$TMP/apply" 6 6 2
CEIL=1100
set +e
node "$TOOL" "$TMP/apply" --ceiling "$CEIL" --apply --json > "$TMP/apply.json"; RC=$?
set -e
check "--apply exits 0" '[[ "$RC" -eq 0 ]]'
A_OK=$(jsonq "$TMP/apply.json" 'r.invariant.ok')
A_FILES=$(jsonq "$TMP/apply.json" 'r.invariant.files')
A_INDEXED=$(jsonq "$TMP/apply.json" 'r.invariant.indexed_main + r.invariant.indexed_archive')
A_BYTES=$(jsonq "$TMP/apply.json" 'r.bytes_after')
A_TRAILER=$(jsonq "$TMP/apply.json" 'r.invariant.trailer_count_ok')
check "invariant ok after apply" '[[ "$A_OK" == "true" ]]'
check "files == main + archive after apply ($A_FILES == $A_INDEXED)" '[[ "$A_FILES" -eq "$A_INDEXED" ]]'
check "exactly one trailer after apply" '[[ "$A_TRAILER" == "true" ]]'
check "MEMORY.md under the ceiling after apply ($A_BYTES <= $CEIL)" '[[ "$A_BYTES" -le "$CEIL" ]]'
check ".MEMORY.md.prev rotated" '[[ -f "$TMP/apply/.MEMORY.md.prev" ]]'
check "archive created with a dated section" 'grep -q "^## Moved from MEMORY.md" "$TMP/apply/MEMORY-ARCHIVE.md"'
check "trailer links the archive by exact name" 'grep -q "\[MEMORY-ARCHIVE.md\](MEMORY-ARCHIVE.md)" "$TMP/apply/MEMORY.md"'

# 6. usage
set +e
node "$TOOL" > /dev/null 2>&1; RC=$?   # silent: known-noise -- usage error text is the expected output here
set -e
check "no dir is usage (exit 2)" '[[ "$RC" -eq 2 ]]'
set +e
node "$TOOL" --help > /dev/null; RC=$?
set -e
check "--help exits 0" '[[ "$RC" -eq 0 ]]'

echo "SKILL.md"
N200=$(awk '/200 lines/{n++} END{print n+0}' "$SKILL")
check "stale '200 lines' rule removed from dream SKILL.md" '[[ "$N200" -eq 0 ]]'
check "SKILL.md invokes index-budget.mjs" 'grep -q "index-budget.mjs" "$SKILL"'
check "SKILL.md states the two-file invariant" 'grep -q "MEMORY-ARCHIVE.md" "$SKILL"'

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ "$FAIL" -eq 0 ]]
